struct fat_header
{
	uint32_t magic;		/* FAT_MAGIC */
	uint32_t nfat_arch; /* number of structs that follow */
};

struct fat_arch
{
	cpu_type_t cputype;		  /* cpu specifier (int) */
	cpu_subtype_t cpusubtype; /* machine specifier (int) */
	uint32_t offset;		  /* file offset to this object file */
	uint32_t size;			  /* size of this object file */
	uint32_t align;			  /* alignment as a power of 2 */
};

struct mach_header
{
	uint32_t magic;			  /* mach magic number identifier */
	cpu_type_t cputype;		  /* cpu specifier */
	cpu_subtype_t cpusubtype; /* machine specifier */
	uint32_t filetype;		  /* type of file */
	uint32_t ncmds;			  /* number of load commands */
	uint32_t sizeofcmds;	  /* the size of all the load commands */
	uint32_t flags;			  /* flags */
};

struct load_command
{
	uint32_t cmd;	 /* type of load command */
	uint32_t cmdsize; /* total size of command in bytes */
};

struct uuid_command {
  uint32_t cmd;
  uint32_t cmdsize;
  uint8_t uuid[16];
};

struct entry_point_command {
  uint32_t cmd;
  uint32_t cmdsize;
  uint64_t entryoff;
  uint64_t stacksize;
};

struct codesignature_command {
	uint32_t cmd;
	uint32_t cmdsize;
	uint32_t dataoff;
	uint32_t datasize;
};

struct encryption_info_command {
    uint32_t cmd;
    uint32_t cmdsize;
    uint32_t cryptoff;
    uint32_t cryptsize;
    uint32_t cryptid;
};

struct encryption_info_command_64
{
	uint32_t cmd;
	uint32_t cmdsize;
	uint32_t cryptoff;
	uint32_t cryptsize;
	uint32_t cryptid;
	uint32_t pad;
};

union lc_str {
	uint32_t	offset;		/* offset to the string */
};

struct dylib {
    union lc_str   	name;			/* library's path name */
    uint32_t 		timestamp;			/* library's build time stamp */
    uint32_t 		current_version;		/* library's current version number */
    uint32_t 		compatibility_version;	/* library's compatibility vers number*/
};

struct dylib_command {
	uint32_t		cmd;		/* LC_ID_DYLIB, LC_LOAD_{,WEAK_}DYLIB,LC_REEXPORT_DYLIB */
	uint32_t		cmdsize;	/* includes pathname string */
	struct dylib	dylib;		/* the library identification */
};

struct CS_BlobIndex {
	uint32_t type;					/* type of entry */
	uint32_t offset;				/* offset of entry */
};

struct CS_SuperBlob {
	uint32_t magic;					/* magic number */
	uint32_t length;				/* total length of SuperBlob */
	uint32_t count;					/* number of index entries following */
	//CS_BlobIndex index[];			/* (count) entries */
	/* followed by Blobs in no particular order as indicated by offsets in index */
};

struct CS_Entitlement {
	uint32_t magic;
	uint32_t length;
};

struct CS_GenericBlob {
	uint32_t magic;					/* magic number */
	uint32_t length;				/* total length of blob */
};

struct CS_Scatter {
	uint32_t count;					// number of pages; zero for sentinel (only)
	uint32_t base;					// first page number
	uint64_t targetOffset;			// offset in target
	uint64_t spare;					// reserved
};

