std::string folder = std::string(tmp_root) + "/zfuzz_bundle_" + std::to_string((unsigned long long)suf);
// Ensure the folder exists; if creation fails, bail since the API requires a writable folder.
if (!ZFile::CreateFolder(folder.c_str())) { FUZZ_BAIL(); }

// Seed minimal app-bundle-like structure to cover more code paths.
// Create an Info.plist with random content and a small binary to simulate contents.
{
    std::string info_plist = folder + "/Info.plist";
    std::string info_data = FUZZ_PARAM_STR();
    // Keep small for speed.
    if (info_data.size() > 1024) info_data.resize(1024);
    ZFile::WriteFile(info_plist.c_str(), info_data);
}
{
    std::string bin_path = folder + "/MockBinary";
    std::string bin_data = FUZZ_PARAM_STR();
    if (bin_data.size() > 1024) bin_data.resize(1024);
    ZFile::WriteFile(bin_path.c_str(), bin_data);
}

// Build optional dylib list (0 or 1 entry) and create the file(s) if present.
std::vector<std::string> arrDylibFiles;
if ((*FUZZ_PARAM(unsigned int) & 1u) == 1u) {
    std::string dylib_path = folder + "/libinject_" + std::to_string((unsigned long long)(*FUZZ_PARAM(unsigned int))) + ".dylib";
    std::string dylib_data = FUZZ_PARAM_STR();
    if (dylib_data.size() > 512) dylib_data.resize(512);
    ZFile::WriteFile(dylib_path.c_str(), dylib_data);
    arrDylibFiles.push_back(dylib_path);
}

// Generate parameters: bundle id, version, display name. Constrain sizes and characters for plausibility.
auto make_ascii = [](std::string s) {
    if (s.size() > 128) s.resize(128);
    for (char& c : s) { if (static_cast<unsigned char>(c) < 0x20 || static_cast<unsigned char>(c) > 0x7E) c = 'a'; }
    return s;
};
// Bundle ID: use dot-separated tokens; sanitize heavily.
std::string raw_bid = FUZZ_PARAM_STR();
std::string bundle_id;
{
    if (raw_bid.empty()) raw_bid = "a";
    // Map non [A-Za-z0-9.] to 'a', collapse leading dots.
    bundle_id.reserve(raw_bid.size());
    for (char ch : raw_bid) {
        bool ok = (ch == '.') || (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z');
        bundle_id.push_back(ok ? ch : 'a');
    }
    if (bundle_id.size() > 64) bundle_id.resize(64);
    if (!bundle_id.empty() && bundle_id.front() == '.') bundle_id.front() = 'a';
    if (bundle_id.empty()) bundle_id = "a.b";
}
// Version and display name can be generic sanitized strings.
std::string bundle_version = make_ascii(FUZZ_PARAM_STR());
if (bundle_version.empty()) bundle_version = "1.0";
std::string display_name = make_ascii(FUZZ_PARAM_STR());
if (display_name.empty()) display_name = "App";

// Flags
bool bForce       = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
bool bWeakInject  = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
bool bEnableCache = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;

// Invoke the target API. The return indicates success/failure; both are acceptable here.
( void )bundle->SignFolder(
    pSignAsset,
    folder,
    bundle_id,
    bundle_version,
    display_name,
    arrDylibFiles,
    bForce,
    bWeakInject,
    bEnableCache
);

