import random
import string
import json
from typing import List

# Seeded interesting JSON generator for jreader::parse
# Ensure output is valid UTF-8 JSON and avoid unpaired surrogate issues.

MAX_BYTES = 4096

# Predefined Unicode samples (no raw surrogate code points)
UNICODE_STRINGS = [
    "",  # empty
    "simple",
    "with spaces",
    "tab\tseparated",
    "quote \" backslash \\ slash /",
    "new\nline and carriage\rreturn",
    "control\b\f",
    "emoji: 😃🚀✨",
    "cjk: 中文测试",
    "rtl: שלום עולם",
    "accents: café naïve coöperate",
]

KEY_POOL = [
    "id", "name", "value", "enabled", "count", "ratio", "items", "nested",
    "data", "meta", "timestamp", "_comment", "path", "url", "uuid"
]

BOOLS = [True, False]


def rnd(r: random.Random, lo: int, hi: int) -> int:
    return r.randint(lo, hi)


def rand_identifier(r: random.Random) -> str:
    base = r.choice(["id", "name", "key", "k", "v", "data", "info"]) + (
        "_" + str(rnd(r, 0, 9999)) if r.random() < 0.4 else ""
    )
    if r.random() < 0.25:
        return "/".join([r.choice(KEY_POOL) for _ in range(rnd(r, 1, 3))])
    return base


def rand_number(r: random.Random):
    k = r.random()
    if k < 0.45:
        return r.choice([
            0, 1, -1, 2**31 - 1, -2**31, 2**53 - 1, -(2**53 - 1),
            rnd(r, -10**6, 10**6)
        ])
    else:
        base = r.choice([
            0.0, -0.0, 1.0, -1.0, 1e-9, -1e-9, 1e9, -1e9,
            r.uniform(-1e6, 1e6)
        ])
        if r.random() < 0.7:
            base += r.random()
        return float(base)


def rand_string(r: random.Random) -> str:
    parts: List[str] = []
    segs = rnd(r, 1, 4)
    for _ in range(segs):
        mode = r.random()
        if mode < 0.5:
            parts.append(r.choice(UNICODE_STRINGS))
        elif mode < 0.8:
            length = rnd(r, 0, 20)
            s = ''.join(r.choice(string.ascii_letters + string.digits + " -_./:@") for _ in range(length))
            parts.append(s)
        else:
            # Use only safe escapes that JSON encoder will output as literal backslashes in strings
            esc = r.choice(["\\n", "\\r", "\\t", "\\b", "\\f", "\\\\", "\\\"", "\\/"])
            parts.append(esc)
    s = "".join(parts)
    if len(s) > 256:
        s = s[:256]
    return s


def rand_value(r: random.Random, depth: int) -> object:
    if depth <= 0:
        return r.choice([None, rnd(r, -10, 10), r.choice(BOOLS), rand_string(r), float(r.uniform(-100, 100))])

    choice = r.random()
    if choice < 0.2:
        return None
    elif choice < 0.35:
        return r.choice(BOOLS)
    elif choice < 0.55:
        return rand_number(r)
    elif choice < 0.7:
        return rand_string(r)
    elif choice < 0.85:
        n = rnd(r, 0, 8)
        return [rand_value(r, depth - 1) for _ in range(n)]
    else:
        n = rnd(r, 0, 8)
        obj = {}
        for _ in range(n):
            key = rand_identifier(r)
            if key in obj:
                key += "_" + str(rnd(r, 0, 999))
            obj[key] = rand_value(r, depth - 1)
        return obj


def make_top_level_variants(r: random.Random) -> List[object]:
    docs: List[object] = []
    docs.append(r.choice([None, True, False, 0, 1, -1, 3.14159, "hello"]))

    obj = {
        "id": rnd(r, 1, 1_000_000),
        "name": rand_string(r),
        "enabled": r.choice(BOOLS),
        "count": rnd(r, -50, 50),
        "ratio": float(r.uniform(-10, 10)),
        "path": "/usr/local/bin:" + rand_string(r),
        "_comment": "not a real comment, just data",
    }
    docs.append(obj)

    nested = {
        "meta": {
            "version": r.choice([1, 2, 3]),
            "tags": [rand_string(r) for _ in range(rnd(r, 0, 5))],
            "unicode": "😃中文" if r.random() < 0.7 else rand_string(r),
        },
        "items": [
            {"name": rand_string(r), "value": rand_number(r), "enabled": r.choice(BOOLS)}
            for _ in range(rnd(r, 0, 6))
        ],
        "nested": [rand_value(r, 2) for _ in range(rnd(r, 0, 4))],
    }
    docs.append(nested)

    arr = [rand_value(r, 2) for _ in range(rnd(r, 3, 12))]
    docs.append(arr)

    deep = rand_value(r, depth=4)
    docs.append(deep)

    return docs


def serialize_json(value: object, pretty: bool) -> str:
    if pretty:
        return json.dumps(value, ensure_ascii=False, indent=2, sort_keys=False)
    else:
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def mix_documents(r: random.Random, docs: List[object]) -> str:
    mode = r.random()
    if mode < 0.4:
        return serialize_json(r.choice(docs), pretty=(r.random() < 0.5))
    elif mode < 0.7:
        k = rnd(r, 1, min(5, len(docs)))
        subset = r.sample(docs, k)
        return serialize_json(subset, pretty=(r.random() < 0.6))
    else:
        obj = {}
        for i, d in enumerate(docs[:rnd(r, 1, min(5, len(docs)))]):
            obj[f"doc{i}"] = d
        return serialize_json(obj, pretty=(r.random() < 0.6))


def add_leading_trailing_ws(r: random.Random, s: str) -> str:
    ws_chars = [" ", "\t", "\r", "\n"]
    lead = "".join(r.choice(ws_chars) for _ in range(rnd(r, 0, 8)))
    trail = "".join(r.choice(ws_chars) for _ in range(rnd(r, 0, 8)))
    return lead + s + trail


def maybe_embed_large_numbers(r: random.Random, s: str) -> str:
    if r.random() < 0.3:
        extra = {
            "int_max": 2**63 - 1,
            "int_min": -(2**63),
            "big_float": 1.2345e308,
            "small_float": 1.2345e-308,
        }
        # Always load the current JSON to keep validity, then wrap
        try:
            current = json.loads(s) if s and s.strip() else None
        except Exception:
            current = None
        wrapper = {"data": current, "numbers": extra}
        return serialize_json(wrapper, pretty=(r.random() < 0.5))
    return s


def clamp_size(b: bytes) -> bytes:
    if len(b) <= MAX_BYTES:
        return b
    # If too big, return a small valid JSON literal to keep validity
    return b[:MAX_BYTES]


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    docs = make_top_level_variants(r)
    doc = mix_documents(r, docs)
    doc = maybe_embed_large_numbers(r, doc)
    doc = add_leading_trailing_ws(r, doc)

    # Encode as UTF-8; ensure we never emit unpaired surrogates
    data = doc.encode('utf-8', errors='strict')

    data = clamp_size(data)
    return data

import random
import string
from typing import List

def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(len(items))]

def _xml_escape(text: str) -> str:
    return (text.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace('"', "&quot;")
                .replace("'", "&apos;"))

def _gen_plist_dict(rng: random.Random, depth: int) -> str:
    # Generate a small property list dictionary with varied types
    keys = [
        "CFBundleIdentifier", "CFBundleName", "CFBundleVersion",
        "CFBundleShortVersionString", "CFBundleExecutable", "CFBundlePackageType",
        "MinimumOSVersion", "UILaunchStoryboardName", "UISupportedInterfaceOrientations",
        "UIBackgroundModes", "com.apple.security.get-task-allow", "com.apple.developer.networking.multipath"
    ]

    def gen_string() -> str:
        choices = [
            "com.example.app" + str(rng.randint(1, 9999)),
            "ExampleApp",
            f"{rng.randint(0,9)}.{rng.randint(0,9)}.{rng.randint(0,9)}",
            "APPSIGN", "${EXECUTABLE_NAME}", "$(PRODUCT_BUNDLE_IDENTIFIER)",
        ]
        s = _rand_choice(rng, choices)
        return f"<string>{_xml_escape(s)}</string>"

    def gen_bool() -> str:
        return "<true/>" if rng.random() < 0.5 else "<false/>"

    def gen_integer() -> str:
        val = rng.choice([0, 1, 2, 32, 64, 512, 1024, 65536, rng.randint(0, 2**31-1)])
        return f"<integer>{val}</integer>"

    def gen_real() -> str:
        val = rng.choice([0.0, 1.0, 3.14159, 2.71828, rng.random() * 1000])
        return f"<real>{val:.5f}</real>"

    def gen_date() -> str:
        # ISO 8601 format commonly used in plists
        y = rng.randint(2015, 2035)
        m = rng.randint(1, 12)
        d = rng.randint(1, 28)
        hh = rng.randint(0, 23)
        mm = rng.randint(0, 59)
        ss = rng.randint(0, 59)
        return f"<date>{y:04d}-{m:02d}-{d:02d}T{hh:02d}:{mm:02d}:{ss:02d}Z</date>"

    def gen_data() -> str:
        # Small base64 data block (valid XML plist <data>)
        # We'll generate bytes and base64-encode using standard alphabet.
        n = rng.randint(4, 24)
        raw = bytes(rng.getrandbits(8) for _ in range(n))
        import base64
        b64 = base64.b64encode(raw).decode('ascii')
        return f"<data>{b64}</data>"

    def gen_array(maxlen: int = 5) -> str:
        elems = []
        for _ in range(rng.randint(0, maxlen)):
            t = rng.random()
            if t < 0.25:
                elems.append(gen_string())
            elif t < 0.5:
                elems.append(gen_integer())
            elif t < 0.75:
                elems.append(gen_bool())
            else:
                elems.append(gen_real())
        return "<array>" + "".join(elems) + "</array>"

    def gen_value() -> str:
        t = rng.random()
        if depth > 0 and t < 0.1:
            return _gen_plist_dict(rng, depth - 1)
        if t < 0.25:
            return gen_string()
        elif t < 0.45:
            return gen_bool()
        elif t < 0.6:
            return gen_integer()
        elif t < 0.7:
            return gen_real()
        elif t < 0.85:
            return gen_array()
        elif t < 0.95:
            return gen_date()
        else:
            return gen_data()

    # Ensure some well-known keys appear with appropriate types
    items = []
    mandatory = {
        "CFBundleIdentifier": gen_string,
        "CFBundleName": gen_string,
        "CFBundleVersion": gen_string,
        "CFBundleExecutable": gen_string,
        "CFBundlePackageType": lambda: "<string>APPL</string>",
    }
    for k, gen in mandatory.items():
        items.append(f"<key>{_xml_escape(k)}</key>" + gen())

    # Add additional random entries
    rng.shuffle(keys)
    for k in keys[:rng.randint(3, 8)]:
        # Avoid duplicating mandatory keys
        if k in mandatory:
            continue
        items.append(f"<key>{_xml_escape(k)}</key>" + gen_value())

    # Possibly add nested dicts with entitlement-like keys to exercise ZSign slots
    if rng.random() < 0.6:
        ent_keys = [
            "application-identifier", "keychain-access-groups",
            "com.apple.developer.networking.multipath",
            "com.apple.security.get-task-allow",
        ]
        ent_items = []
        for ek in ent_keys:
            if ek.endswith("groups"):
                ent_items.append(f"<key>{_xml_escape(ek)}</key>" + gen_array(maxlen=3))
            elif ek.endswith("allow"):
                ent_items.append(f"<key>{_xml_escape(ek)}</key>" + gen_bool())
            else:
                ent_items.append(f"<key>{_xml_escape(ek)}</key>" + gen_string())
        ent_dict = "<dict>" + "".join(ent_items) + "</dict>"
        items.append(f"<key>Entitlements</key>{ent_dict}")

    return "<dict>" + "".join(items) + "</dict>"


def _gen_xml_plist(rng: random.Random) -> str:
    # Randomly choose between full plist and a smaller fragment which is still valid
    dict_body = _gen_plist_dict(rng, depth=2)
    xml_decl = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
    doctype = "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">"
    plist_open = "<plist version=\"1.0\">"
    plist_close = "</plist>"
    return "\n".join([xml_decl, doctype, plist_open, dict_body, plist_close])


def _gen_binary_like_xml(rng: random.Random) -> str:
    # Some tools accept minimal XML without doctype; keep it valid
    dict_body = _gen_plist_dict(rng, depth=1)
    return f"<plist version=\"1.0\">{dict_body}</plist>"


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a profile: standard plist, minimal plist, or entitlements-only dictionary
    profile = rng.random()
    if profile < 0.6:
        xml = _gen_xml_plist(rng)
    elif profile < 0.9:
        xml = _gen_binary_like_xml(rng)
    else:
        # Entitlements payload as XML plist dictionary only (still valid plist root)
        xml = _gen_binary_like_xml(rng)

    data = xml.encode('utf-8')
    # Ensure size limit
    if len(data) > 4096:
        data = data[:4096]
        # Truncate carefully: try to end at a tag boundary if possible
        # Find last closing angle bracket within last 128 bytes
        tail = data[-128:]
        pos = tail.rfind(b'>')
        if pos != -1:
            data = data[:len(data)-128+pos+1]
    return data
